//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_symbol_properties_identity_own_keys_and_no_native_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,a=Symbol('same'),b=Symbol('same'),v={value:3};var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});d[a]=v;d[b]=7;if(d[a]!==v||d[b]!==7||d!==n.dataset||Object.keys(d).length||Object.getOwnPropertyNames(d).length||watch.takeRecords().length||n.attributes.length!==1)throw 'separate native Symbol backing';var keys=Object.getOwnPropertySymbols(d);if(keys.length!==2||keys[0]!==a||keys[1]!==b||Reflect.ownKeys(d)[1]!==b)throw 'own Symbol identity and insertion order';var desc=Object.getOwnPropertyDescriptor(d,a);if(desc.value!==v||!desc.writable||!desc.enumerable||!desc.configurable)throw 'assignment own descriptor';delete d[a];d[a]=9;keys=Object.getOwnPropertySymbols(d);if(keys[0]!==b||keys[1]!==a||watch.takeRecords().length)throw 'Symbol reinsertion order';"#);}

#[test]
fn dataset_symbol_properties_native_scalar_raw_and_symbol_keys_remain_separate(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset,s=Symbol('x'),watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});d[s]={native:false};if(watch.takeRecords().length)throw 'Symbol does not mutate attributes';d.first='one';d['x\ud800Name']='raw';if(n.getAttribute('data-first')!=='one'||n.getAttributeNS(null,'data-x\ud800-name')!=='raw'||Object.keys(d).length!==2||Object.keys(d)[1]!=='x\ud800Name'||typeof d[s]!=='object')throw 'strings still native';var keys=Reflect.ownKeys(d);if(keys.length!==3||keys[0]!=='first'||keys[1]!=='x\ud800Name'||keys[2]!==s||Object.values(d).length!==2)throw 'native strings precede Symbols';delete d.first;delete d['x\ud800Name'];if(!delete d[s]||n.hasAttributes()!==true||Object.keys(d).length||Object.getOwnPropertySymbols(d).length)throw 'independent deletion';}"#);}

#[test]
fn dataset_symbol_properties_data_and_accessor_descriptors_keep_flags_and_receiver(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,a=Symbol(),b=Symbol(),hits=0;Object.defineProperty(d,a,{value:3});d[a]=8;if(d[a]!==3||delete d[a]||Object.getOwnPropertySymbols(d).length!==1)throw 'ordinary Symbol data flags';var caught;try{Object.defineProperty(d,a,{value:8});}catch(e){caught=e;}if(!(caught instanceof TypeError)||d[a]!==3)throw 'nonconfigurable Symbol';Object.defineProperty(d,b,{get:function(){if(this!==d)throw 'getter receiver';hits++;return 7;},set:function(v){if(this!==d||v!==9)throw 'setter receiver';hits++;},enumerable:true,configurable:true});d[b]=9;if(d[b]!==7||hits!==2||Object.getOwnPropertyDescriptor(d,b).get===undefined||n.hasAttribute('data-undefined'))throw 'Symbol accessors';if(!delete d[b])throw 'delete configurable accessor';"#);}

#[test]
fn dataset_symbol_properties_actual_prototype_symbols_and_class_tag_remain_live(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,s=Symbol(),seen=0;Object.defineProperty(DOMStringMap.prototype,s,{get:function(){if(this!==d)throw 'prototype receiver';seen++;return 4;},set:function(v){if(this!==d||v!==8)throw 'prototype setter';seen++;},configurable:true});if(d[s]!==4||!(s in d)||Object.prototype.hasOwnProperty.call(d,s))throw 'inherited Symbol lookup';d[s]=8;if(seen!==2||Object.getOwnPropertySymbols(d).length||Object.prototype.toString.call(d)!=='[object DOMStringMap]')throw 'prototype identity and class tag';var own=Symbol();d[own]=1;d[Symbol.toStringTag]='Ignored';if(Object.prototype.toString.call(d)!=='[object DOMStringMap]')throw 'inherited tag is read-only';Object.defineProperty(d,Symbol.toStringTag,{value:'OwnTag',configurable:true});if(Object.prototype.toString.call(d)!=='[object OwnTag]')throw 'own class tag';delete d[Symbol.toStringTag];if(Object.prototype.toString.call(d)!=='[object DOMStringMap]')throw 'restored inherited class tag';delete DOMStringMap.prototype[s];if(s in d||d[s]!==undefined||d[own]!==1)throw 'live prototype deletion';"#);}

#[test]
fn dataset_symbol_properties_bulk_definition_assign_and_descriptor_snapshots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,a=Symbol(),b=Symbol(),v={token:1},descs={first:{value:'native'}};descs[a]={value:v,writable:true,enumerable:true,configurable:true};descs[b]={value:9};if(Object.defineProperties(d,descs)!==d||d.first!=='native'||d[a]!==v||d[b]!==9)throw 'bulk string and Symbol definitions';var all=Object.getOwnPropertyDescriptors(d);if(all[a].value!==v||all[b].enumerable||all.first.value!=='native')throw 'descriptor snapshot';var copy=Object.assign({},d),other=document.createElement('p').dataset;if(copy.first!=='native'||copy[a]!==v||Object.prototype.hasOwnProperty.call(copy,b))throw 'enumerable Symbols copy';if(Object.assign(other,d)!==other||other.first!=='native'||other[a]!==v||Object.getOwnPropertySymbols(other).length!==1)throw 'native Symbol assignment target';"#);}

#[test]
fn dataset_symbol_properties_reflect_set_symbol_preserves_ordinary_receiver_and_flags(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,s=Symbol(),v={same:true},other={};if(!Reflect.set(d,s,v)||d[s]!==v)throw 'same receiver native Symbol';if(!Reflect.set(d,s,4,other)||other[s]!==4||d[s]!==v)throw 'different ordinary receiver';Object.defineProperty(d,s,{writable:false});if(Reflect.set(d,s,8)!==false||Reflect.set(d,s,8,{})!==false||d[s]!==v)throw 'own readonly Symbol descriptor';var next=Symbol();if(!Reflect.set({},next,v,d)||d[next]!==v)throw 'native Symbol receiver from ordinary target';"#);}

#[test]
fn dataset_symbol_properties_retained_closure_is_live_across_real_entry_collection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,slot=Symbol();(function(){var held=[17];d[slot]=function(){return ++held[0];};})();if(d[slot]()!==18)throw 'initial retained closure';"#);run(&mut d,&mut f,&mut p,r#"if(d[slot]()!==19||d[slot]()!==20)throw 'retained closure after entry collection';"#);}
